"""Shared bits for the reference generators: where the rustinfer tree is, and
how to write a page header."""
import os
import pathlib
import subprocess

HERE = pathlib.Path(__file__).resolve().parent
SITE = HERE.parent.parent
CONTENT = SITE / "content"
RUSTINFER = pathlib.Path(os.environ.get("RUSTINFER_SRC", SITE.parent / "rustinfer")).resolve()

GENERATED_NOTE = ("<!-- Generated by scripts/reference/{script} from the rustinfer "
                  "checkout; do not edit by hand. Regenerate with "
                  "`.venv/bin/python scripts/reference/{script}`. -->\n")


def commit():
    try:
        return subprocess.check_output(["git", "-C", str(RUSTINFER), "log", "-1",
                                        "--format=%h %ad", "--date=short"],
                                       text=True).strip()
    except Exception:  # noqa: BLE001
        return "unknown"


def branch():
    try:
        return subprocess.check_output(["git", "-C", str(RUSTINFER), "branch",
                                        "--show-current"], text=True).strip()
    except Exception:  # noqa: BLE001
        return "unknown"


def header(title, section, order, summary, group="", navtitle="", script=""):
    lines = ["---", f"title: {title}"]
    if navtitle:
        lines.append(f"navtitle: {navtitle}")
    lines.append(f"section: {section}")
    if group:
        lines.append(f"group: {group}")
    lines += [f"order: {order}", f"summary: {summary}", "---", ""]
    out = "\n".join(lines)
    if script:
        out += GENERATED_NOTE.format(script=script)
    return out


def write(name, text):
    (CONTENT / name).write_text(text, encoding="utf-8")
    print(f"wrote {name} ({len(text.splitlines())} lines)")
